  background: #0e1522;
  padding: 16px;
  position: sticky;
  top: 65px;
  height: calc(100vh - 65px);
  overflow: auto;
}
.sidebar h3 { margin-top: 0; }
.sidebar a {
  display: block;
  color: var(--text-muted);
  padding: 8px 10px;
  border-radius: 8px;
  margin-bottom: 6px;
}
.sidebar a:hover,
.sidebar a.active {
  color: var(--text);
  background: #182131;
  text-decoration: none;
}
.sidebar-collapsed .docs-layout { grid-template-columns: 74px 1fr; }
.sidebar-collapsed .sidebar {
  width: 74px;
  padding: 12px 8px;
}
.sidebar-collapsed .sidebar h3,
.sidebar-collapsed .sidebar a span { display: none; }

.main-docs {
  padding: 22px;
}
.kpi-grid {
