  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px;
}
.kpi strong { font-size: 1.2rem; display: block; }

footer {
  border-top: 1px solid var(--border);
  padding: 18px 0 26px;
  color: var(--text-muted);
  margin-top: 26px;
}

@media (max-width: 960px) {
  .grid, .kpi-grid, .cli-wrap { grid-template-columns: 1fr; }
